"""Write reviewable versioned delivery only. Coordinator owns sealing/review."""
from pathlib import Path
import json,hashlib
HERE=Path(__file__).resolve().parent;OBJ=HERE.parent;OUT=OBJ/'candidates/round-02'
sha=lambda p:hashlib.sha256(Path(p).read_bytes()).hexdigest()
export=json.loads((OUT/'export-validation.json').read_text());brief=json.loads((OBJ/'brief.json').read_text());validation=json.loads((OUT/'validation.json').read_text())
def raw(record):
 p=Path(record['path']);clip,direction=p.parent.name.rsplit('-',1)
 return {'clip':clip,'direction':direction,'index':int(p.stem),'path':record['path'],'sha256':record['sha256']}
def atlas(record):return {**record,'clip':record['id'],'size':[2304,1280],'frameWidth':384,'frameHeight':640,'frames':12}
mainRaw=[raw(r) for r in export['frames'] if r['mode']=='main'];runtimeRaw=[raw(r) for r in export['frames'] if r['mode']=='runtime'];mainAtlases=[atlas(r) for r in export['atlases'] if r['mode']=='main'];runtimeAtlases=[atlas(r) for r in export['atlases'] if r['mode']=='runtime']
previews={name:f'candidates/round-02/playback/{name}.webm' for name in brief['capture']['previews'] if name not in ['four-view-sheet','repeated']}
previews.update({'four-view-sheet':'candidates/round-02/four-view-sheet.png','repeated':'candidates/round-02/light-background.png','source-directions':'candidates/round-02/source-direction-proof.png','background-gray':'candidates/round-02/gray-background.png','background-dark':'candidates/round-02/dark-background.png','context-seated':'candidates/round-02/seated-wait-stool-context.png','context-eat-cucumber':'candidates/round-02/eat-stool-context.png','context-eat-salmon':'candidates/round-02/eat-salmon-stool-context.png','context-empty':'candidates/round-02/seated-wait-empty-stool-context.png','phone-eat-salmon':'candidates/round-02/browser-phone-eat-salmon.png','phone-empty-dark':'candidates/round-02/browser-phone-empty-dark.png'})
resources=[]
# Explicitly bind all retained failed .blend1 files, native frames, media and logs.
# The coordinator's generic source recursion intentionally skips some extensions.
for base in [OBJ/'source',OBJ/'candidates']:
 for f in sorted(base.rglob('*')):
  if not f.is_file() or '__pycache__' in f.parts or f.name in ['.DS_Store','packet.json','delivery.snapshot.json']:continue
  path=f.relative_to(OBJ).as_posix();role='current-candidate' if path.startswith('candidates/round-02/') else ('retained-unsealed-draft' if 'draft-01-hand-weights' in path or '/round-01/' in path or 'round01' in path or 'round-01.' in path else 'native-source-or-reproduction')
  resources.append({'path':path,'sha256':sha(f),'role':role})
for name in ['proposed-source-contract.json','proposed-food-mappings.json','initial.json','proposedcriteria.json','main-audit.json','runtime-audit.json','main-contact-baselines.json','runtime-contact-baselines.json']:
 f=OBJ/'reviews'/name;resources.append({'path':f.relative_to(OBJ).as_posix(),'sha256':sha(f),'role':'frozen-original-judge-evidence'})
delivery={'asset':'customer-ellis','round':'round-02','status':'complete native handoff; awaiting original independent judge; not sealed or approved','project':'source/round-02.blend','recipeScript':'source/reproduce_round02.py','source':{'blend':'source/round-02.blend','sha256':sha(HERE/'round-02.blend'),'actuallyExecutedRecipe':'source/build_round02.py','actuallyExecutedRecipeSHA256':sha(HERE/'build_round02.py'),'reproductionScript':'source/reproduce_round02.py','portablePathAdapterValidation':'candidates/round-02/portable-reproduction-validation.json'},'validation':'candidates/round-02/validation.json','nativeRecords':{'camera':'source/round-02-camera.json','assetRecord':'source/round-02-asset.json','rig':'source/resources/main-rig.json'},'heroes':{d:f'candidates/round-02/frames/stand-{d}/000.png' for d in 'NESW'},'rawFrames':mainRaw,'atlases':mainAtlases,'previews':previews,'resources':resources,'runtimeVariants':{'project':'source/round-02-runtime.blend','projectSHA256':sha(HERE/'round-02-runtime.blend'),'nativeRecords':{'camera':'source/round-02-runtime-camera.json','assetRecord':'source/round-02-runtime-asset.json','rig':'source/resources/runtime-rig.json'},'rawFrames':runtimeRaw,'atlases':runtimeAtlases,'clips':[r for r in export['clips'] if r['mode']=='runtime'],'constraint':'Supplemental runtime only; original catalog remains10states. Main and runtime share all44 body mesh coordinates, weights/groups, material recipe, lights and render settings.'},'counts':{'mainNativeFrames':480,'mainAtlases':40,'mainActual12fpsClips':40,'supplementalNativeFrames':96,'supplementalAtlases':8,'supplementalActual12fpsClips':8,'completeNativeFrames':576,'boundResourceFiles':len(resources)},'frozenInputs':{'briefSHA256':sha(OBJ/'brief.json'),'foodMappingSHA256':sha(OBJ/'reviews/proposed-food-mappings.json'),'sourceContractSHA256':sha(OBJ/'reviews/proposed-source-contract.json')},'technicalSummary':{'rigRestAndActionsPreserved':validation['restMatchesSource'] and validation['actionsMatchSource'],'bodyParity':validation['bodyParity'],'clearanceFailures':validation['envelopeFailures'],'maxEvaluatedFunctionalSurfaceErrorWorld':validation['evaluatedFunctionalSurfaceMaximumWorld'],'nativeAuditMaxErrors':validation['nativeAuditMaxErrors'],'browserPlayback':validation['browserPlayback'],'wholeCanvasAtlasCopies':not validation['atlasWholeCanvasCopyFailures'],'PNGAlphaEdgeFailures':len(validation['alphaEdgeFailures'])},'failedDraft':{'source':'source/draft-01-hand-weights','outputs':'candidates/draft-01-hand-weights','manifest':'source/draft-01-hand-weights/immutable-manifest.json','explanation':'source/draft-01-hand-weights/failure.json','explicitResourceFileCount':sum('draft-01-hand-weights' in r['path'] for r in resources)},'notes':'source/round-02-handoff-notes.txt','limitations':validation['limits']+['Desktop actual playback dropped0frames;390x844phone maximum2decoder frames dropped, recorded with all48clip-direction states and all nonloops ending.']}
assert len(mainRaw)==480 and len(runtimeRaw)==96 and len(mainAtlases)==40 and len(runtimeAtlases)==8
assert set(brief['capture']['previews'])<=set(previews)
assert all((OBJ/p).is_file() for p in previews.values())
assert all(sha(OBJ/r['path'])==r['sha256'] for r in resources)
for record in delivery['nativeRecords'].values():assert (OBJ/record).is_file()
path=OBJ/'delivery.round-02.json';path.write_text(json.dumps(delivery,indent=2)+'\n')
print('ELLIS_HANDOFF',path,sha(path),'resources',len(resources),'failedClosure',delivery['failedDraft']['explicitResourceFileCount'],flush=True)
print('MAIN',delivery['source']['sha256'],'RUNTIME',delivery['runtimeVariants']['projectSHA256'],flush=True)
